function createTodoElement(todo) {
  var li = document.createElement('li');
  li.dataset.id = todo.id;
  if (todo.completed) li.classList.add('completed');

  li.innerHTML =
    '<div class="view">' +
      '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
      '<label>' + escapeHtml(todo.title) + '</label>' +
      '<button class="destroy"></button>' +
    '</div>' +
    '<input class="edit" value="' + escapeHtml(todo.title) + '">';

  return li;
}

function updateItem(li, todo) {
  if (todo.completed && !li.classList.contains('completed')) {
    li.classList.add('completed');
  } else if (!todo.completed && li.classList.contains('completed')) {
    li.classList.remove('completed');
  }
  var label = li.querySelector('.view label');
  if (label && label.textContent !== todo.title) {
    label.textContent = todo.title;
  }
  var edit = li.querySelector('.edit');
  if (edit && edit.value !== todo.title) {
    edit.value = todo.title;
  }
  var checkbox = li.querySelector('.toggle');
  if (checkbox && checkbox.checked !== todo.completed) {
    checkbox.checked = todo.completed;
  }
}

